package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Refuses an add whose name another person on the sheet already has, or a contact another person on the sheet has. */
public class CheckNameFree {
    public void check(@PathVariable("sheetId") String sheetId, @Val PersonRequest request, PersonStore store)
            throws DuplicateNameException, DuplicateContactException {
        if (store.nameTaken(sheetId.trim(), request.name(), null)) {
            throw new DuplicateNameException(request.name());
        }
        if (request.contact() != null && store.contactTaken(sheetId.trim(), request.contact(), null)) {
            throw new DuplicateContactException(request.contact());
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;

/** Refuses an edit to a name another person on the sheet already has, or a contact another person on the sheet has. */
public class CheckNameFreeForEdit {
    public void check(@Val PersonRequest request, @Val Person person, PersonStore store)
            throws DuplicateNameException, DuplicateContactException {
        if (store.nameTaken(person.getSheetId(), request.name(), person.getId())) {
            throw new DuplicateNameException(request.name());
        }
        if (request.contact() != null && store.contactTaken(person.getSheetId(), request.contact(), person.getId())) {
            throw new DuplicateContactException(request.contact());
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;

/** Adds the alias to the person's aliases, refusing one that equals, ignoring case, any name or alias on the sheet. */
public class AddAlias {
    public void add(@Val AliasRequest request, @Val Person person, PersonStore store) throws DuplicateNameException {
        if (store.nameTaken(person.getSheetId(), request.alias(), null)) {
            throw new DuplicateNameException(request.alias());
        }
        store.addAlias(person, request.alias());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Refuses a blank alias; publishes it without the spaces around it. */
public class ValidateAlias {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody AliasRequest request,
            Out<AliasRequest> body, RoleStore roles) throws InvalidSheetException {
        roles.refuseChange(sheetId.trim(), request == null ? null : request.user());
        String alias = request == null || request.alias() == null ? "" : request.alias().trim();
        if (alias.isEmpty()) {
            throw new InvalidSheetException("An alias is required");
        }
        body.set(new AliasRequest(alias, request.user()));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.InvalidSheetException;

/** A name already in use by another person on the sheet; refused like any invalid change (400). */
public class DuplicateNameException extends InvalidSheetException {
    public DuplicateNameException(String name) {
        super("The name " + name + " is already in use");
    }
}
